diff --git a/scripts/test-sampling.ts b/scripts/test-sampling.ts
new file mode 100644
index 0000000..bf57422
--- /dev/null
+++ b/scripts/test-sampling.ts
@@ -0,0 +1,16 @@
+import { readFileSync } from 'node:fs';
+
+const src = readFileSync(new URL('../gemini.ts', import.meta.url), 'utf8');
+const m = /export function supportsSamplingParams[\s\S]*?\n}\n/.exec(src);
+if (!m) { console.error('supportsSamplingParams missing'); process.exit(1); }
+const fn = new Function(m[0].replace('export function', 'function').replace(/: string|: boolean/g, '') + '; return supportsSamplingParams;')();
+
+const cases: [string, boolean][] = [
+  ['gemini-2.5-pro', true], ['gemini-3.5-flash-lite', true], ['gemini-3.8-flash', false],
+  ['gemini-3.10-pro', false], ['gemini-4.0-pro', false], ['custom-local-model', true],
+];
+let bad = 0;
+for (const [id, want] of cases) if (fn(id) !== want) { console.error('FAIL', id); bad++; }
+if (/temperature: 0\.9,\s*\n\s*\};/.test(src)) { console.error('unconditional temperature 0.9 in chat config'); bad++; }
+if (!/supportsSamplingParams\(model\)\) config\.temperature/.test(src)) { console.error('chat config not gated'); bad++; }
+process.exit(bad ? 1 : 0);

